#include <zephyr/ztest.h>
#include <pthread.h>
#include <limits.h>

#define STACK_SIZE (512 + CONFIG_TEST_EXTRA_STACK_SIZE)
#define MAX_NO_OF_THREADS (PTHREAD_KEYS_MAX / 2)

static pthread_key_t key_1toN;
K_THREAD_STACK_ARRAY_DEFINE(stacks, MAX_NO_OF_THREADS, STACK_SIZE);

static void *key_1toN_thread_entry(void *p1)
{
	int ret;
	pthread_t tid;

	ret = pthread_setspecific(key_1toN, (void *)pthread_self());
	zassert_equal(ret, 0, "pthread_setspecific failed");

	/* Let other threads run */
	k_yield();

	tid = (pthread_t)pthread_getspecific(key_1toN);
	zassert_equal(tid, pthread_self(), "pthread_getspecific failed");

	return NULL;
}

/**
 * @brief Test to verify thread specific data for 1-N threads
 * @see pthread_key_create(), pthread_setspecific(), pthread_getspecific()
 * @see pthread_create(), pthread_join(), pthread_key_delete()
 */
ZTEST(key, test_key_1toN_thread)
{
	int ret;
	pthread_t tid[MAX_NO_OF_THREADS];
	pthread_attr_t attr;

	ret = pthread_key_create(&key_1toN, NULL);
	zassert_equal(ret, 0, "pthread_key_create failed");

	zassert_ok(pthread_attr_init(&attr));

	for (int i = 0; i < MAX_NO_OF_THREADS; i++) {
		pthread_attr_setstack(&attr, &stacks[i][0], STACK_SIZE);
		ret = pthread_create(&tid[i], &attr, key_1toN_thread_entry,
				   NULL);
		zassert_equal(ret, 0, "pthread_create failed");
	}

	for (int i = 0; i < MAX_NO_OF_THREADS; i++) {
		ret = pthread_join(tid[i], NULL);
		zassert_equal(ret, 0, "pthread_join failed");
	}

	ret = pthread_key_delete(key_1toN);
	zassert_equal(ret, 0, "pthread_key_delete failed");

	pthread_attr_destroy(&attr);
}

/**
 * @brief Test to verify that correct key is deleted
 * @see pthread_key_create(), pthread_key_delete()
 */
ZTEST(key, test_correct_key_is_deleted)
{
	int ret;
	pthread_key_t key[PTHREAD_KEYS_MAX];
	pthread_key_t temp_key;

	/* Create max number of keys */
	for (int i = 0; i < PTHREAD_KEYS_MAX; i++) {
		ret = pthread_key_create(&key[i], NULL);
		zassert_equal(ret, 0, "pthread_key_create failed");
	}

	/* Try to create one more key */
	ret = pthread_key_create(&temp_key, NULL);
	zassert_equal(ret, EAGAIN, "pthread_key_create should have failed");

	/* Delete a key and try to create a key again */
	ret = pthread_key_delete(key[PTHREAD_KEYS_MAX - 1]);
	zassert_equal(ret, 0, "pthread_key_delete failed");

	ret = pthread_key_create(&temp_key, NULL);
	zassert_equal(ret, 0, "pthread_key_create succeeded");
	zassert_equal(temp_key, key[PTHREAD_KEYS_MAX - 1], "key not reused");

	/* Cleanup */
	for (int i = 0; i < PTHREAD_KEYS_MAX - 1; i++) {
		ret = pthread_key_delete(key[i]);
		zassert_equal(ret, 0, "pthread_key_delete failed");
	}

	ret = pthread_key_delete(temp_key);
	zassert_equal(ret, 0, "pthread_key_delete failed");
}

ZTEST_SUITE(key, NULL, NULL, NULL, NULL, NULL);
